import { defineCollection } from 'astro:content';
import { glob } from 'astro/loaders';
import { z } from 'astro/zod';

// Entries are generated by scripts/import-wp.mjs; edit the JSON files directly.
const entry = z.object({
  title: z.string(),
  path: z.string(),
  wpId: z.number(),
  parent: z.number(),
  order: z.number(),
  date: z.string(),
  modified: z.string(),
  description: z.string(),
  image: z.string().nullable(),
  excerpt: z.string(),
  categories: z.array(z.string()),
  hasForm: z.boolean(),
  html: z.string(),
});

export const collections = {
  pages: defineCollection({ loader: glob({ pattern: '*.json', base: './src/content/pages' }), schema: entry }),
  posts: defineCollection({ loader: glob({ pattern: '*.json', base: './src/content/posts' }), schema: entry }),
};
